class Stack {
    private final ArrayList<Integer> items = new ArrayList<>();

    void push(int x) {
        items.add(x);                            // add on top
    }

    Integer pop() {
        if (isEmpty()) return null;              // underflow: nothing to take
        return items.remove(items.size() - 1);   // remove the top
    }

    Integer peek() {
        return isEmpty() ? null : items.get(items.size() - 1);   // look, don't remove
    }

    boolean isEmpty() {
        return items.isEmpty();
    }

    int size() {
        return items.size();
    }
}

class Stack {
    vector<int> items;

public:
    void push(int x) {
        items.push_back(x);                  // add on top
    }

    int pop() {
        if (isEmpty()) throw out_of_range("pop from an empty stack");   // underflow
        int x = items.back();                // remember the top
        items.pop_back();                    // then remove it
        return x;
    }

    int peek() {
        if (isEmpty()) throw out_of_range("peek at an empty stack");
        return items.back();                 // look, don't remove
    }

    bool isEmpty() {
        return items.empty();
    }

    int size() {
        return items.size();
    }
};
